import net.createmod.ponder.api.scene.Selection;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.Property;
import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.fluids.ForgeFlowingFluid;
import net.minecraftforge.fluids.capability.IFluidHandler;

public class CrucibleScenes {
    public static void crucible(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("industrial_crucible", "Build up Industrial Crucible");
        scene.configureBasePlate(0, 0, 6);
        scene.showBasePlate();
        scene.idle(10);
        Selection crucible = util.select().fromTo(2, 1, 2, 4, 3, 4);
        Selection largeCog1 = util.select().position(2, 0, 6);
        Selection shaft = util.select().fromTo(1, 1, 4, 1, 1, 6);
        Selection pipe = util.select().fromTo(0, 1, 3, 0, 1, 6).add(util.select().position(1, 1, 3)).add(util.select().position(0, 0, 6));
        BlockPos crucibleController = util.grid().at(2, 2, 2);
        scene.world().showIndependentSection(crucible, Direction.DOWN);
        scene.idle(10);
        scene.overlay().showText(80).attachKeyFrame().text("Industrial Crucibles can be used to store molten metals").pointAt(util.vector().blockSurface(util.grid().at(3, 3, 2), Direction.NORTH)).placeNearTarget();
        scene.idle(90);
        scene.overlay().showText(80).attachKeyFrame().colored(PonderPalette.GREEN).text("You can add windows with a Wrench!").pointAt(util.vector().blockSurface(util.grid().at(3, 3, 2), Direction.NORTH)).placeNearTarget();
        scene.idle(90);
        scene.overlay().showControls(util.vector().blockSurface(crucibleController, Direction.WEST), Pointing.LEFT, 15).rightClick().withItem(AllItems.WRENCH.asStack());
        for (int i = 0; i < 3; ++i) {
            scene.world().modifyBlock(util.grid().at(2, 1 + i, 2), s -> (BlockState)s.m_61124_((Property)CrucibleBlock.WINDOW, (Comparable)Boolean.valueOf(true)), false);
            scene.idle(5);
        }
        scene.world().showSection(pipe, Direction.EAST);
        scene.idle(5);
        scene.world().showSection(largeCog1, Direction.NORTH);
        scene.world().showSection(shaft, Direction.DOWN);
        scene.idle(5);
        List<FluidStack> fluids = List.of(new FluidStack(((ForgeFlowingFluid.Flowing)CMFluids.MOLTEN_GOLD.get()).m_5613_(), 1000), new FluidStack(((ForgeFlowingFluid.Flowing)CMFluids.MOLTEN_IRON.get()).m_5613_(), 1000), new FluidStack(((ForgeFlowingFluid.Flowing)CMFluids.MOLTEN_OBDURIUM.get()).m_5613_(), 1000), new FluidStack(((ForgeFlowingFluid.Flowing)CMFluids.MOLTEN_SLAG.get()).m_5613_(), 1000));
        for (FluidStack fluid : fluids) {
            scene.world().modifyBlockEntity(util.grid().at(1, 0, 6), FluidTankBlockEntity.class, be -> be.getTankInventory().fill(fluid, IFluidHandler.FluidAction.EXECUTE));
            scene.idle(20);
        }
        scene.overlay().showText(80).attachKeyFrame().colored(PonderPalette.MEDIUM).text("Crucibles can also store multiple fluids at the same time!").pointAt(util.vector().blockSurface(crucibleController, Direction.WEST)).placeNearTarget();
        scene.idle(90);
        scene.markAsFinished();
    }

