        scene.idle(5);
        scene.world().showSection(util.select().position(redstonePos), Direction.DOWN);
        scene.idle(5);
        scene.world().showSection(whiteBulb, Direction.DOWN);
        scene.idle(10);
        scene.overlay().showText(80).attachKeyFrame().text("Light Bulbs are an alternative light source to the Redstone Lamp").pointAt(whiteBulbVec).placeNearTarget();
        scene.idle(90);
        scene.overlay().showText(80).attachKeyFrame().text("They emit light proportionally to the strength of the Redstone signal received").pointAt(whiteBulbVec).placeNearTarget();
