import net.minecraftforge.registries.tags.ITagManager;

public class TagDependentBucketItem
extends BucketItem {
    private TagKey<Item> tag;

    public TagDependentBucketItem(Supplier<? extends Fluid> supplier, Item.Properties builder, TagKey<Item> tag) {
        super(supplier, builder);
        this.tag = tag;
    }

    public boolean shouldHide() {
        ITagManager tagManager = ForgeRegistries.ITEMS.tags();
        return !tagManager.isKnownTagName(this.tag) || tagManager.getTag(this.tag).isEmpty();
